add('ex', 20, 7, 'Matthew Henry', 'Não tomarás o nome em vão — O nome de Deus é sagrado e merece reverência.', 'teologico', 'resumo');
add('ex', 24, 7, 'Matthew Henry', 'O Senhor escreveu — A aliança é ratificada com sangue.', 'teologico', 'resumo');
add('ex', 25, 8, 'Matthew Henry', 'Farás uma arca — A arca da aliança é o centro da presença de Deus.', 'teologico', 'resumo');
add('ex', 33, 14, 'Matthew Henry', 'Mostrarei a tua glória — Deus concede a Moisés uma visão parcial de sua glória.', 'teologico', 'resumo');
