add('js', 1, 8, 'Joshua Harris', 'Não se aparte da tua boca — A meditação constante na Lei produz prosperidade espiritual e obediência.', 'aplicacao', 'resumo');
add('js', 1, 9, 'Spurgeon', 'O Senhor teu Deus é contigo — A presença de Deus é a fonte de toda a coragem. Se Deus está connosco, quem estará contra nós?', 'aplicacao', 'resumo');
