// RT (21 comentários)
add('rt', 1, 16, 'Spurgeon', 'Não me peças que te deixe — A fidelidade nos relacionamentos é sinal da fé em Deus. Rute é um retrato de Cristo.', 'aplicacao', 'resumo');
add('rt', 4, 14, 'Lutero', 'O Senhor não te deixou sem resgatador — A providência de Deus opera através de parentes redentores.', 'teologico', 'resumo');
