add('is', 6, 8, 'Lutero', 'A disponibilidade para a missão divina. O crente responde ao chamado de Deus com prontidão, independentemente do custo.', 'aplicacao', 'resumo');
add('is', 7, 14, 'Calvino', 'A profecia messiânica de Emanuel. A encarnação de Cristo é o cumprimento desta promessa milenar.', 'escatologico', 'resumo');
add('is', 9, 6, 'N.T. Wright', 'A realeza de Cristo é eterna. Ele é o conselheiro maravilhoso, o Deus fortificado, o Pai eterno, o Príncipe da paz.', 'escatologico', 'resumo');
